const sectionHeadings = ['Define the work unit', 'Capture facts before action', 'Make the handoff inspectable', 'Handle the exception path', 'Protect judgment and access', 'Use a first-batch scorecard', 'Review the operating fit'];

function makePost(topic: Aug18Topic) {
  const paragraphs = [
    `${topic.audience} can use a Philippines-based remote assistant when ${topic.unit} is digital, repeatable, and reviewed by someone who understands the underlying work. The useful question is not whether an assistant can “help” in the abstract. It is whether the source information can be handled safely, the finished record can be recognized, and an exception can stop at the right person.`,
    `Start by writing the unit in plain language: ${topic.unit}. That definition gives the assistant a countable piece of work instead of a vague responsibility. It also lets the owner compare the written request with the record that came back. If several kinds of requests arrive, keep them as separate lanes until their rules are understood.`,
    `The first intake should collect ${topic.inputs}. Those fields are not a substitute for professional judgment; they are the minimum context needed to prevent a reviewer from searching through scattered messages. Mark unknown information as missing rather than filling it from guesswork. A visible gap is safer than a confident but unsupported value.`,
    `The finished item should be ${topic.output}. Put the source message or file beside the record, use a consistent date and owner field, and name the next action. A reviewer should be able to answer three questions quickly: what arrived, what was done, and what still requires an accountable decision.`,
    `The most important stop rule addresses ${topic.risk}. When that condition appears, the assistant should preserve the source, note the uncertainty, and route it to ${topic.review}. The handoff should say what is known and what is not known. It should never convert a request for preparation into an approval, diagnosis, promise, or conclusion.`,
    `Consider this ordinary case: ${topic.example}. A useful record would show the received information, the missing fact, the person who owns the question, and the time when it should be revisited. That structure keeps the assistant productive without asking the assistant to improvise a decision that belongs to the local team or a qualified professional.`,
    `Access should follow the work unit. Give the assistant the queue, source material, and named account needed to prepare ${topic.output}; keep ${topic.boundary} with the accountable owner. Prefer individual accounts, limited permissions, and a clear way to revoke access. The owner should also decide how sensitive records are redacted before examples are shared.`,
    `A narrow first batch makes quality visible. The reviewer can compare the submitted record with the source, mark a correction, and update the instruction when the same question returns. If the assistant repeatedly encounters a missing field, repair the intake or example before increasing volume. More activity does not fix an unclear workflow.`,
    `The scorecard should count ${topic.measure}. Do not treat raw volume as the goal. A queue that is fast but incomplete creates work for the person who must repair it. Pair completed units with returned items, unanswered questions, aging records, and access exceptions. These measures show whether the handoff is becoming easier to supervise.`,
    `Keep local and remote responsibilities separate. The remote assistant can organize online records, draft neutral notes, and surface missing information. The local operator may still need to speak with a customer, inspect a property, assess a situation, or make a regulated decision. Stating that boundary protects the business and gives the assistant a fair description of the job.`,
    `At the weekly review, select a few completed records and one exception. Ask whether the source is traceable, the fields are accurate, and the next owner action is obvious. Ask the assistant which instruction caused hesitation. The review is a conversation about the system as well as the person; recurring questions usually point to a process gap.`,
    `Do not hide policy in a shortcut phrase such as “handle as usual.” Replace it with an example, a stop rule, and an escalation destination. For this workflow, the owner should decide ${topic.decision}. That decision can be recorded in the operating note so a future reviewer sees why the field, queue, or boundary exists.`,
    `A first-month handoff can stay deliberately small: prepare the records, review them daily at first, and add only one adjacent task after the original lane is stable. If a new task changes the risk, source data, or approval owner, treat it as a new lane. That prevents a useful assistant role from quietly becoming an undefined catch-all position.`,
    `The practical test is simple. Can a new reviewer open the source, understand the record, see the unresolved question, and identify who decides next? If yes, the workflow is ready for measured use. If not, improve the brief before blaming the worker. Clear work, limited access, and an explicit escalation path are the foundation of dependable remote assistant support.`,
  ];
  return {
    slug: topic.slug,
    mainKeyword: topic.keyword,
    title: topic.title,
    excerpt: `Plan ${topic.keyword} around a defined work unit, source-linked records, and an approval boundary that keeps judgment with the accountable team.`,
    published: topic.published,
    richPublished: true,
    minutes: 10,
    image: '/images/calendar-assistant.jpg',
    imageAlt: `${topic.title} workflow planning at a remote desk`,
    takeaways: [`Start with ${topic.unit}.`, `Capture ${topic.inputs}.`, `Escalate ${topic.risk}.`, `Measure ${topic.measure}.`],
    detail: {
      revision: `2026-08-18-${topic.slug}-r1`,
      directAnswer: [paragraphs[0], paragraphs[3]],
      bodyLinks: [{ href: '/blog/virtual-assistant-security-checklist', label: 'review the remote assistant security checklist' }, { href: '/blog/local-vs-remote-administrative-assistant-benchmark-2026', label: 'compare local and remote task fit' }],
      sections: sectionHeadings.map((heading, index) => ({ heading, paragraphs: [paragraphs[index * 2 + 1], paragraphs[index * 2 + 2]] })),
      decisionRows: [{ need: 'Online preparation and record keeping', fit: 'Philippines-based remote assistant', reason: 'The output can be defined, sourced, and reviewed.' }, { need: 'Physical or regulated judgment', fit: 'Local or qualified owner', reason: 'The work depends on presence, authority, or professional judgment.' }, { need: 'Unclear exception', fit: 'Pause and escalate', reason: 'The assistant preserves facts and waits for the named reviewer.' }, { need: 'Mixed workflow', fit: 'Split the lanes', reason: 'Separate preparation from approval and field work.' }],
      planningNumbers: [{ value: '1 unit', label: 'First scope', note: topic.unit }, { value: '1 reviewer', label: 'Decision owner', note: topic.review }, { value: '1 stop rule', label: 'Main risk', note: topic.risk }, { value: '7 days', label: 'First review', note: 'Inspect a small batch before adding volume.' }],
      scripts: [{ title: 'Role brief', text: `Prepare ${topic.unit} from the approved queue. Record ${topic.inputs}, link the source, and escalate ${topic.risk} to ${topic.review}.` }, { title: 'Review question', text: `Can we verify ${topic.output} from the source, and is the next decision clearly assigned to ${topic.review}?` }],
      scenario: { title: `Sample workflow: ${topic.keyword}`, intro: 'Use this sequence to turn an incoming request into a checkable first task lane.', steps: [{ step: '1', title: 'Receive', body: `Save the source for ${topic.unit} and note when it arrived.` }, { step: '2', title: 'Record', body: `Enter ${topic.inputs} without guessing at missing information.` }, { step: '3', title: 'Check', body: `Compare the record with the example and flag ${topic.risk}.` }, { step: '4', title: 'Route', body: `Send the completed item or exception to ${topic.review}.` }, { step: '5', title: 'Learn', body: `Use the review to decide ${topic.decision}.` }] },
      faqs: [{ question: `What is the first unit for ${topic.keyword}?`, answer: `Start with ${topic.unit}, using ${topic.inputs} as the minimum source context.` }, { question: 'What should the remote assistant never decide?', answer: `Keep ${topic.boundary} with the accountable owner or qualified professional.` }, { question: 'How should exceptions be handled?', answer: `Preserve the source, describe the missing or conflicting fact, and route it to ${topic.review}.` }, { question: 'What should the first review measure?', answer: `Measure ${topic.measure}, along with corrections and items waiting on a decision.` }, { question: 'Where are assistants recruited?', answer: 'This service recruits and hires assistants in the Philippines for remote work.' }],
      relatedLinks: [{ href: '/blog/virtual-assistant-security-checklist', label: 'Set access rules before handoff' }, { href: '/blog/local-vs-remote-administrative-assistant-benchmark-2026', label: 'Compare local and remote task fit' }, { href: '/blog', label: 'Browse all hiring guides' }, { href: '/contact-us', label: 'Prepare a role brief' }],
      sources: [{ name: 'CISA, Turn on Multifactor Authentication', url: 'https://www.cisa.gov/secure-our-world/turn-mfa', note: 'Account sign-in guidance.' }, { name: 'FTC Business Guidance', url: 'https://www.ftc.gov/business-guidance', note: 'General business and data-handling guidance.' }],
    },
  };
}

